//! Exact reply-message fixtures generated by the pinned TypeScript reference.

use std::error::Error;

use keri_protocol::event::kind::EventKind;
use keri_protocol::event::reply::ReplyBuilder;
use keri_protocol::event::timestamp::{Timestamp, TimestampError};
use keri_protocol::serialization::{Sad, SadValue};
use serde::Deserialize;

const REFERENCE_SHA: &str = "91a04a5edd804425f42be75ffbf034f8d14e5cb2";

#[derive(Debug, Deserialize)]
struct Fixture {
    schema_version: u8,
    upstream: String,
    reference_sha: String,
    generated_on: String,
    sources: Vec<String>,
    exported_builders: Vec<String>,
    ilks: Vec<String>,
    cases: Vec<ReplyCase>,
    reference_quirks: ReferenceQuirks,
}

#[derive(Debug, Deserialize)]
struct ReplyCase {
    name: String,
    route: String,
    timestamp: String,
    attributes_json: String,
    said: String,
    version_string: String,
    raw: String,
    raw_hex: String,
    raw_byte_size: usize,
}

#[derive(Debug, Deserialize)]
struct ReferenceQuirks {
    the_timestamp_defaults_to_the_system_clock: ClockQuirk,
    any_string_is_accepted_as_a_timestamp: LooseStampQuirk,
    attributes_need_not_be_a_map: LooseAttributesQuirk,
    null_attributes_become_an_empty_map: NullAttributesQuirk,
    the_post_derivation_check_is_unreachable: UnreachableCheckQuirk,
}

#[derive(Debug, Deserialize)]
struct ClockQuirk {
    shape: String,
    length: usize,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct LooseStampQuirk {
    garbage: String,
    empty: String,
    note: String,
    rust_error_category: String,
}

#[derive(Debug, Deserialize)]
struct LooseAttributesQuirk {
    string: String,
    array: String,
    number: String,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct NullAttributesQuirk {
    raw: String,
    note: String,
    rust_decision: String,
}

#[derive(Debug, Deserialize)]
struct UnreachableCheckQuirk {
    note: String,
    rust_decision: String,
}

fn fixture() -> Result<Fixture, Box<dyn Error>> {
    Ok(serde_json::from_str(include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/reply/v1.json"
    )))?)
}

fn decode_hex(input: &str) -> Result<Vec<u8>, Box<dyn Error>> {
    if !input.len().is_multiple_of(2) {
        return Err("odd-length hexadecimal fixture field".into());
    }
    (0..input.len())
        .step_by(2)
        .map(|index| {
            input
                .get(index..index + 2)
                .ok_or_else(|| Box::<dyn Error>::from("hexadecimal fixture slice out of range"))
                .and_then(|pair| u8::from_str_radix(pair, 16).map_err(Into::into))
        })
        .collect()
}

#[test]
fn fixture_metadata_matches_the_pinned_reference() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.upstream, "https://github.com/WebOfTrust/signify-ts.git");
    assert_eq!(fixture.reference_sha, REFERENCE_SHA);
    assert_ne!(fixture.generated_on, "");
    assert_eq!(
        fixture.sources,
        ["src/keri/core/eventing.ts", "test/app/aiding.test.ts"]
    );
    Ok(())
}

/// The evidence behind this item's `N/A` decisions: the reference has no receipt, query, or
/// key-state builder to port, and the `qry` ilk is absent from its table entirely.
#[test]
fn the_reference_exports_only_one_supporting_builder() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(
        fixture.exported_builders,
        ["ample", "incept", "interact", "messagize", "reply", "rotate"]
    );
    // Four of these are key-event builders and `messagize` is attachment composition, leaving
    // `reply` alone here.
    for absent in ["receipt", "query", "state", "keyState", "ksn"] {
        assert!(
            !fixture.exported_builders.iter().any(|name| name == absent),
            "the reference unexpectedly exports {absent}"
        );
    }

    // The ilk table names receipts but nothing constructs one; `qry` is not even declared.
    assert!(fixture.ilks.iter().any(|ilk| ilk == "rct"));
    assert!(fixture.ilks.iter().any(|ilk| ilk == "vrc"));
    assert!(!fixture.ilks.iter().any(|ilk| ilk == "qry"));
    // Rust's own table agrees.
    let rust: Vec<&str> = EventKind::ALL.iter().map(|kind| kind.as_str()).collect();
    for ilk in &fixture.ilks {
        assert!(rust.contains(&ilk.as_str()), "Rust is missing ilk {ilk}");
    }
    assert_eq!(rust.len(), fixture.ilks.len());
    Ok(())
}

#[test]
fn every_reference_reply_is_reproduced_byte_for_byte() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    assert_eq!(fixture.cases.len(), 6);

    for case in &fixture.cases {
        let expected = decode_hex(&case.raw_hex)?;
        assert_eq!(expected, case.raw.as_bytes(), "case {} hex/text disagree", case.name);
        assert_eq!(expected.len(), case.raw_byte_size, "case {}", case.name);

        let attributes = Sad::from_json_bytes(case.attributes_json.as_bytes())?;
        let timestamp = Timestamp::parse(&case.timestamp)?;
        let reply = ReplyBuilder::new(case.route.clone(), timestamp)
            .attributes(attributes)
            .build()?;

        assert_eq!(
            core::str::from_utf8(reply.raw())?,
            case.raw,
            "case {} bytes differ",
            case.name
        );
        assert_eq!(reply.said().qb64()?, case.said, "case {}", case.name);
        assert_eq!(
            reply.sad().get_text("v"),
            Some(case.version_string.as_str()),
            "case {}",
            case.name
        );
        assert_eq!(reply.route(), Some(case.route.as_str()), "case {}", case.name);
        assert_eq!(reply.raw().len(), case.raw_byte_size, "case {}", case.name);
    }
    Ok(())
}

#[test]
fn reference_quirks_are_pinned_and_safely_diverged() -> Result<(), Box<dyn Error>> {
    let fixture = fixture()?;
    let quirks = &fixture.reference_quirks;
    let stamp = Timestamp::parse("2021-06-27T21:26:21.233257+00:00")?;

    // 1. The timestamp defaults to the system clock, so the message depends on when it was built.
    let clock = &quirks.the_timestamp_defaults_to_the_system_clock;
    assert_eq!(clock.length, Timestamp::LENGTH);
    // The recorded shape is digit-masked so the fixture stays reproducible.
    assert_eq!(clock.shape, "9999-99-99T99:99:99.999999+99:99");
    assert_ne!(clock.note, "");
    assert!(clock.rust_decision.contains("required"));
    // Rust cannot build a reply without being told the time, so two builds always agree.
    let first = ReplyBuilder::new("/x", stamp.clone()).build()?;
    let second = ReplyBuilder::new("/x", stamp.clone()).build()?;
    assert_eq!(first.raw(), second.raw());

    // 2. Any string passes as a timestamp upstream.
    let loose = &quirks.any_string_is_accepted_as_a_timestamp;
    assert!(loose.garbage.contains(r#""dt":"not-a-timestamp""#));
    assert!(loose.empty.contains(r#""dt":"""#));
    assert_ne!(loose.note, "");
    assert_eq!(loose.rust_error_category, "TimestampError");
    for text in ["not-a-timestamp", ""] {
        assert!(
            matches!(Timestamp::parse(text), Err(TimestampError::InvalidLength { .. })),
            "{text} was accepted as a timestamp"
        );
    }

    // 3. Attributes need not be a map upstream; in Rust they always are.
    let attributes = &quirks.attributes_need_not_be_a_map;
    assert!(attributes.string.contains(r#""a":"hello""#));
    assert!(attributes.array.contains(r#""a":[1,2]"#));
    assert!(attributes.number.contains(r#""a":42"#));
    assert_ne!(attributes.note, "");
    assert_ne!(attributes.rust_decision, "");
    // The Rust builder takes a `Sad`, so a bare scalar cannot be supplied at all; the closest
    // expressible message wraps it, which is a different -- and well-formed -- document.
    let mut wrapped = Sad::new();
    wrapped.insert("value", SadValue::text("hello"))?;
    let reply = ReplyBuilder::new("/x", stamp.clone()).attributes(wrapped).build()?;
    assert!(core::str::from_utf8(reply.raw())?.contains(r#""a":{"value":"hello"}"#));

    // 4. Null attributes silently become an empty map.
    let null = &quirks.null_attributes_become_an_empty_map;
    assert!(null.raw.contains(r#""a":{}"#));
    assert_ne!(null.note, "");
    assert_ne!(null.rust_decision, "");
    let empty = ReplyBuilder::new("/x", stamp.clone()).build()?;
    assert!(core::str::from_utf8(empty.raw())?.contains(r#""a":{}"#));

    // 5. The reference re-verifies the SAID it just derived, which can never fail.
    let unreachable = &quirks.the_post_derivation_check_is_unreachable;
    assert_ne!(unreachable.note, "");
    assert_ne!(unreachable.rust_decision, "");
    // Rust derives once and the invariant still holds.
    let derived = ReplyBuilder::new("/end/role/add", stamp).build()?;
    assert_eq!(derived.sad().get_text("d"), Some(derived.said().qb64()?.as_str()));
    Ok(())
}
